import { test } from "node:test";
import assert from "node:assert/strict";
import { ApiClient } from "../src/client.js";

const reply = (status, body = {}) => ({ ok: status < 400, status, json: async () => body });

test("get returns the body", async () => {
  const c = new ApiClient("https://x", async () => reply(200, { a: 1 }));
  assert.deepEqual(await c.get("/a"), { a: 1 });
});

test("get retries a 503 and then succeeds", async () => {
  const replies = [reply(503), reply(200, { ok: true })];
  const c = new ApiClient("https://x", async () => replies.shift(), { delayMs: 1 });
  assert.deepEqual(await c.get("/a"), { ok: true });
});

test("get does not retry a 404", async () => {
  let calls = 0;
  const c = new ApiClient("https://x", async () => (calls++, reply(404)), { delayMs: 1 });
  await assert.rejects(c.get("/a"), /404/);
  assert.equal(calls, 1);
});

